// Demo: Jupyter - related Anomaly Detection Trainer technology
(function(){'use strict';
var DATA={"label": "Jupyter - related Anomaly Detection Trainer technology", "arr": [83, 21, 31, 25, 98, 23, 1, 86]};

var a=DATA.arr.slice(),cmp=0,sw=0;
function qs(lo,hi){if(lo>=hi)return;var piv=a[hi],i=lo;
  for(var j=lo;j<hi;j++){cmp++;if(a[j]<piv){var t=a[i];a[i]=a[j];a[j]=t;i++;sw++;}}
  var t2=a[i];a[i]=a[hi];a[hi]=t2;sw++;qs(lo,i-1);qs(i+1,hi);}
console.log('Quicksort ('+DATA.label+'): input ['+DATA.arr.join(', ')+']');
qs(0,a.length-1);
console.log('sorted: ['+a.join(', ')+']');
console.log('comparisons='+cmp+' swaps='+sw);
})();

